// PR: https://github.com/tidalcycles/strudel/issues/670
let binpatn = (dec, len) => seq(
  ...(typeof dec === 'string' ? [1] :
    dec.toString(2)
    .padStart(len, '0')
    .split('')
    .map(Number)
     )
)
// registers a binpat mask with the given length
let maskn = (n) => register('mask'+n, (dec, pat) => 
  pat.mask(
    reify(dec).fmap(v => binpatn(v, n)).squeezeJoin()
  ), false)

let mask2 = maskn(2)
let mask3 = maskn(3)
let mask4 = maskn(4)
